import java.util.*;
class Solution {
    public int networkDelayTime(int[][] times,int n,int k){
        List<List<int[]>> g=new ArrayList<>();
        for(int i=0;i<=n;i++)g.add(new ArrayList<>());
        for(int[] e:times)g.get(e[0]).add(new int[]{e[1],e[2]});
        int[] dist=new int[n+1];Arrays.fill(dist,Integer.MAX_VALUE);dist[k]=0;
        PriorityQueue<int[]> pq=new PriorityQueue<>((a,b)->Integer.compare(a[0],b[0]));
        pq.offer(new int[]{0,k});
        while(!pq.isEmpty()){
            int[] cur=pq.poll();int d=cur[0],u=cur[1];
            if(d!=dist[u])continue;
            for(int[] e:g.get(u)){
                int v=e[0],nd=d+e[1];
                if(nd<dist[v]){dist[v]=nd;pq.offer(new int[]{nd,v});}
            }
        }
        int best=0;
        for(int i=1;i<=n;i++){
            if(dist[i]==Integer.MAX_VALUE)return -1;
            best=Math.max(best,dist[i]);
        }
        return best;
    }
}

