class Solution {
    public int minCostConnectPoints(int[][] points){
        int n=points.length,total=0;
        boolean[] used=new boolean[n];
        int[] best=new int[n];Arrays.fill(best,Integer.MAX_VALUE);best[0]=0;
        for(int step=0;step<n;step++){
            int u=-1;
            for(int i=0;i<n;i++)if(!used[i]&&(u==-1||best[i]<best[u]))u=i;
            used[u]=true;total+=best[u];
            for(int v=0;v<n;v++)if(!used[v]){
                int cost=Math.abs(points[u][0]-points[v][0])+Math.abs(points[u][1]-points[v][1]);
                best[v]=Math.min(best[v],cost);
            }
        }
        return total;
    }
}

