class Solution {
    public int minimumEffortPath(int[][] heights){
        int m=heights.length,n=heights[0].length;
        int[][] dist=new int[m][n];for(int[] row:dist)Arrays.fill(row,Integer.MAX_VALUE);
        dist[0][0]=0;
        PriorityQueue<int[]> pq=new PriorityQueue<>((a,b)->Integer.compare(a[0],b[0]));
        pq.offer(new int[]{0,0,0});
        int[][] dirs={{1,0},{-1,0},{0,1},{0,-1}};
        while(!pq.isEmpty()){
            int[] cur=pq.poll();int effort=cur[0],r=cur[1],c=cur[2];
            if(effort!=dist[r][c])continue;
            if(r==m-1&&c==n-1)return effort;
            for(int[] d:dirs){
                int x=r+d[0],y=c+d[1];
                if(x<0||y<0||x>=m||y>=n)continue;
                int nd=Math.max(effort,Math.abs(heights[r][c]-heights[x][y]));
                if(nd<dist[x][y]){dist[x][y]=nd;pq.offer(new int[]{nd,x,y});}
            }
        }
        return -1;
    }
}

