import java.util.*;
class Solution {
    public List<String> findItinerary(List<List<String>> tickets){
        Map<String,PriorityQueue<String>> g=new HashMap<>();
        for(List<String> t:tickets)g.computeIfAbsent(t.get(0),k->new PriorityQueue<>()).offer(t.get(1));
        LinkedList<String> route=new LinkedList<>();
        dfs("JFK",g,route);
        return route;
    }
    private void dfs(String airport,Map<String,PriorityQueue<String>> g,LinkedList<String> route){
        PriorityQueue<String> next=g.get(airport);
        while(next!=null&&!next.isEmpty())dfs(next.poll(),g,route);
        route.addFirst(airport);
    }
}

