                    char prev=p.charAt(j-2);
                    if(prev=='.'||prev==s.charAt(i-1))dp[i][j]|=dp[i-1][j];
                }
            }else if(x=='.'||x==s.charAt(i-1))dp[i][j]=dp[i-1][j-1];
        }
        return dp[m][n];
    }
}

